import{_ as c,c as l,f as p,a as s,b as a,e as t,w as o,r as i,d as r}from"./app-Cdz69Ady.js";const u={};function d(k,n){const e=i("RouteLink");return r(),l("div",null,[n[23]||(n[23]=p('<h1 id="oauth-2-1-client" tabindex="-1"><a class="header-anchor" href="#oauth-2-1-client"><span>OAuth 2.1 Client</span></a></h1><p><code>volga-oauth-client</code> is an OAuth 2.1 / OpenID Connect client built on the shared protocol types from <code>volga-oauth-core</code>. It is <strong>independent of the <code>volga</code> server crate</strong> — usable from any Tokio application (a CLI, a background worker, or a volga web app driving a login flow).</p><p>It provides three clients, all sharing the transport policy of <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.ClientConfig.html" target="_blank" rel="noopener noreferrer"><code>ClientConfig</code></a> and the error model of <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/enum.ClientError.html" target="_blank" rel="noopener noreferrer"><code>ClientError</code></a>:</p>',3)),s("ul",null,[n[8]||(n[8]=s("li",null,[s("a",{href:"https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.DiscoveryClient.html",target:"_blank",rel:"noopener noreferrer"},[s("code",null,"DiscoveryClient")]),a(" — fetches Authorization Server Metadata (RFC 8414), Protected Resource Metadata (RFC 9728) and the OpenID Connect provider configuration.")],-1)),s("li",null,[n[1]||(n[1]=s("a",{href:"https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.OAuthClient.html",target:"_blank",rel:"noopener noreferrer"},[s("code",null,"OAuthClient")],-1)),n[2]||(n[2]=a(" — the Authorization Code flow with mandatory PKCE, refresh tokens and resource indicators, plus token persistence. Since ")),n[3]||(n[3]=s("strong",null,"v0.9.8",-1)),n[4]||(n[4]=a(" it also drives the grants that authenticate the ")),n[5]||(n[5]=s("em",null,"client itself",-1)),n[6]||(n[6]=a(" — see ")),t(e,{to:"/en/security-access/machine-to-machine.html"},{default:o(()=>n[0]||(n[0]=[a("Machine-to-Machine Grants")])),_:1,__:[0]}),n[7]||(n[7]=a("."))]),n[9]||(n[9]=s("li",null,[s("a",{href:"https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.RegistrationClient.html",target:"_blank",rel:"noopener noreferrer"},[s("code",null,"RegistrationClient")]),a(" — Dynamic Client Registration (RFC 7591).")],-1))]),s("p",null,[n[11]||(n[11]=a("Since ")),n[12]||(n[12]=s("strong",null,"v0.9.8",-1)),n[13]||(n[13]=a(" the tokens they obtain can also be sender-constrained with ")),n[14]||(n[14]=s("a",{href:"https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.Dpop.html",target:"_blank",rel:"noopener noreferrer"},[s("code",null,"Dpop")],-1)),n[15]||(n[15]=a(" (RFC 9449) — see ")),t(e,{to:"/en/security-access/dpop.html"},{default:o(()=>n[10]||(n[10]=[a("DPoP")])),_:1,__:[10]}),n[16]||(n[16]=a("."))]),n[24]||(n[24]=p(`<h2 id="dependencies" tabindex="-1"><a class="header-anchor" href="#dependencies"><span>Dependencies</span></a></h2><div class="language-toml line-numbers-mode" data-highlighter="prismjs" data-ext="toml"><pre><code class="language-toml"><span class="line"><span class="token punctuation">[</span><span class="token table class-name">dependencies</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token key property">volga-oauth-client</span> <span class="token punctuation">=</span> <span class="token punctuation">{</span> <span class="token key property">version</span> <span class="token punctuation">=</span> <span class="token string">&quot;...&quot;</span> <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="feature-flags" tabindex="-1"><a class="header-anchor" href="#feature-flags"><span>Feature flags</span></a></h3><table><thead><tr><th>Flag</th><th>What it enables</th></tr></thead><tbody><tr><td><code>http1</code> (default)</td><td>HTTP/1.1 via hyper</td></tr><tr><td><code>http2</code></td><td>HTTP/2 via hyper; negotiated through TLS ALPN when combined with <code>http1</code>, used exclusively (prior knowledge over plaintext) without it</td></tr><tr><td><code>private-key-jwt</code></td><td><code>private_key_jwt</code> client authentication (RFC 7523 §2.2) — a client assertion signed with the client&#39;s own key</td></tr><tr><td><code>dpop</code></td><td>DPoP sender-constrained tokens (RFC 9449)</td></tr></tbody></table><p>At least one of <code>http1</code> / <code>http2</code> must be enabled.</p><div class="hint-container info"><p class="hint-container-title">Info</p><p><code>private-key-jwt</code> and <code>dpop</code> are off by default because they are the only parts of the crate that need a JWS signing backend (<code>jsonwebtoken</code> on <code>aws-lc-rs</code>). Every grant, the secret-based authentication methods and public clients work without them.</p></div><h2 id="discovery" tabindex="-1"><a class="header-anchor" href="#discovery"><span>Discovery</span></a></h2><p><a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.DiscoveryClient.html" target="_blank" rel="noopener noreferrer"><code>DiscoveryClient</code></a> resolves the well-known discovery URLs, fetches the documents over HTTPS and validates each against the identifier it was requested for (RFC 8414 §3.3 / RFC 9728 §3.3):</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">use</span> <span class="token namespace">volga_oauth_client<span class="token punctuation">::</span></span><span class="token punctuation">{</span><span class="token class-name">ClientError</span><span class="token punctuation">,</span> <span class="token class-name">DiscoveryClient</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">async</span> <span class="token keyword">fn</span> <span class="token function-definition function">discover</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Result</span><span class="token operator">&lt;</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">ClientError</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> client <span class="token operator">=</span> <span class="token class-name">DiscoveryClient</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// straight from an issuer identifier (RFC 8414, or the OIDC path):</span></span>
<span class="line">    <span class="token keyword">let</span> server <span class="token operator">=</span> client<span class="token punctuation">.</span><span class="token function">fetch_server_metadata</span><span class="token punctuation">(</span><span class="token string">&quot;https://auth.example.com&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// or start from the resource and follow it to its authorization server:</span></span>
<span class="line">    <span class="token keyword">let</span> resource <span class="token operator">=</span> client<span class="token punctuation">.</span><span class="token function">fetch_resource_metadata</span><span class="token punctuation">(</span><span class="token string">&quot;https://api.example.com&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">let</span> server <span class="token operator">=</span> client<span class="token punctuation">.</span><span class="token function">discover_authorization_server</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>resource<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token macro property">assert!</span><span class="token punctuation">(</span>server<span class="token punctuation">.</span>token_endpoint<span class="token punctuation">.</span><span class="token function">is_some</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name">Ok</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.DiscoveryClient.html#method.fetch_server_metadata" target="_blank" rel="noopener noreferrer"><code>fetch_server_metadata</code></a> / <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.DiscoveryClient.html#method.fetch_oidc_metadata" target="_blank" rel="noopener noreferrer"><code>fetch_oidc_metadata</code></a> — the same document shape at the RFC 8414 and OIDC Discovery paths.</li><li><a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.DiscoveryClient.html#method.fetch_resource_metadata" target="_blank" rel="noopener noreferrer"><code>fetch_resource_metadata</code></a> / <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.DiscoveryClient.html#method.fetch_resource_metadata_from_url" target="_blank" rel="noopener noreferrer"><code>fetch_resource_metadata_from_url</code></a> — the latter takes the <code>resource_metadata</code> URL straight from a <code>WWW-Authenticate</code> challenge.</li><li><a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.DiscoveryClient.html#method.discover_authorization_server" target="_blank" rel="noopener noreferrer"><code>discover_authorization_server</code></a> — takes the first advertised authorization server and fetches its metadata, falling back from the RFC 8414 path to the OIDC path automatically.</li><li><a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.DiscoveryClient.html#method.fetch_jwks" target="_blank" rel="noopener noreferrer"><code>fetch_jwks</code></a> / <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.DiscoveryClient.html#method.fetch_jwks_from_url" target="_blank" rel="noopener noreferrer"><code>fetch_jwks_from_url</code></a> — the issuer&#39;s JSON Web Key Set as raw JSON.</li></ul><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>Attach a <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/trait.MetadataCache.html" target="_blank" rel="noopener noreferrer"><code>MetadataCache</code></a> with <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.DiscoveryClient.html#method.with_cache" target="_blank" rel="noopener noreferrer"><code>with_cache(...)</code></a> to reuse your existing storage; discovery documents rarely change. JWKS fetches deliberately bypass the cache in both directions — signing keys rotate, so freshness policy belongs to you.</p></div><h2 id="authorization-code-pkce" tabindex="-1"><a class="header-anchor" href="#authorization-code-pkce"><span>Authorization Code + PKCE</span></a></h2><p><a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.OAuthClient.html" target="_blank" rel="noopener noreferrer"><code>OAuthClient</code></a> drives the OAuth 2.1 Authorization Code flow. PKCE (S256) is generated and applied automatically — it is the protection OAuth 2.1 prescribes for public clients.</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">use</span> <span class="token namespace">std<span class="token punctuation">::</span>sync<span class="token punctuation">::</span></span><span class="token class-name">Arc</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">use</span> <span class="token namespace">volga_oauth_client<span class="token punctuation">::</span></span><span class="token punctuation">{</span><span class="token class-name">ClientError</span><span class="token punctuation">,</span> <span class="token class-name">DiscoveryClient</span><span class="token punctuation">,</span> <span class="token class-name">InMemoryTokenStore</span><span class="token punctuation">,</span> <span class="token class-name">OAuthClient</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">async</span> <span class="token keyword">fn</span> <span class="token function-definition function">authorize</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Result</span><span class="token operator">&lt;</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">ClientError</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> metadata <span class="token operator">=</span> <span class="token class-name">DiscoveryClient</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">fetch_server_metadata</span><span class="token punctuation">(</span><span class="token string">&quot;https://auth.example.com&quot;</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">let</span> client <span class="token operator">=</span> <span class="token class-name">OAuthClient</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token string">&quot;my-client&quot;</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">with_redirect_uri</span><span class="token punctuation">(</span><span class="token string">&quot;https://app.example.com/callback&quot;</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">with_token_store</span><span class="token punctuation">(</span><span class="token class-name">Arc</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token class-name">InMemoryTokenStore</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 1. build the authorization request (state and PKCE are generated)</span></span>
<span class="line">    <span class="token keyword">let</span> auth <span class="token operator">=</span> client</span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">authorization_request</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>metadata<span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">with_scopes</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string">&quot;read&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">with_resource</span><span class="token punctuation">(</span><span class="token string">&quot;https://api.example.com&quot;</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 2. send the user to \`auth.url\`. The provider redirects back to your</span></span>
<span class="line">    <span class="token comment">//    callback with the real \`code\` and \`state\` query parameters — read</span></span>
<span class="line">    <span class="token comment">//    them there. (This snippet reuses the generated \`auth.state\` so the</span></span>
<span class="line">    <span class="token comment">//    check below holds on the happy path.)</span></span>
<span class="line">    <span class="token keyword">let</span> <span class="token punctuation">(</span>code<span class="token punctuation">,</span> state<span class="token punctuation">)</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token string">&quot;the-authorization-code&quot;</span><span class="token punctuation">,</span> auth<span class="token punctuation">.</span>state<span class="token punctuation">.</span><span class="token function">as_str</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// always verify the callback state before exchanging — CSRF protection</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token operator">!</span>auth<span class="token punctuation">.</span><span class="token function">matches_state</span><span class="token punctuation">(</span>state<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token class-name">Ok</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// reject — possible CSRF</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 3. exchange the code for tokens (the PKCE verifier goes along)</span></span>
<span class="line">    <span class="token keyword">let</span> tokens <span class="token operator">=</span> client<span class="token punctuation">.</span><span class="token function">exchange_code</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>metadata<span class="token punctuation">,</span> code<span class="token punctuation">,</span> <span class="token operator">&amp;</span>auth<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    client<span class="token punctuation">.</span><span class="token function">store_tokens</span><span class="token punctuation">(</span><span class="token string">&quot;alice&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>tokens<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 4. later — served from the store, transparently refreshed when stale:</span></span>
<span class="line">    <span class="token keyword">let</span> tokens <span class="token operator">=</span> client<span class="token punctuation">.</span><span class="token function">token</span><span class="token punctuation">(</span><span class="token string">&quot;alice&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>metadata<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name">Ok</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.AuthorizationRequest.html" target="_blank" rel="noopener noreferrer"><code>AuthorizationRequest</code></a> that <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.AuthorizationRequestBuilder.html#method.build" target="_blank" rel="noopener noreferrer"><code>build()</code></a> returns holds the <code>url</code> to redirect to, the <code>state</code> to check on the callback and the PKCE pair. It is <code>Serialize</code>/<code>Deserialize</code>, so a web application can stash it in the session between the redirect and the callback.</p><p>The request builder accepts <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.AuthorizationRequestBuilder.html#method.with_scopes" target="_blank" rel="noopener noreferrer"><code>with_scopes</code></a>, <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.AuthorizationRequestBuilder.html#method.with_resource" target="_blank" rel="noopener noreferrer"><code>with_resource</code></a> (RFC 8707, repeatable), <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.AuthorizationRequestBuilder.html#method.with_state" target="_blank" rel="noopener noreferrer"><code>with_state</code></a> (override the generated value) and <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.AuthorizationRequestBuilder.html#method.with_param" target="_blank" rel="noopener noreferrer"><code>with_param</code></a> (e.g. the OIDC <code>nonce</code> or <code>prompt</code>).</p><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Always verify the callback <code>state</code> with <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.AuthorizationRequest.html#method.matches_state" target="_blank" rel="noopener noreferrer"><code>matches_state</code></a> <strong>before</strong> exchanging the code — it is your CSRF defence.</p></div><h3 id="validating-the-callback" tabindex="-1"><a class="header-anchor" href="#validating-the-callback"><span>Validating the callback</span></a></h3><p>Since <strong>v0.9.6</strong>, <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.AuthorizationRequest.html#method.validate_callback" target="_blank" rel="noopener noreferrer"><code>validate_callback</code></a> checks the whole callback at once — the <code>state</code> <em>and</em> the RFC 9207 <code>iss</code> parameter — and is the recommended replacement for a bare <code>matches_state</code>:</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">use</span> <span class="token namespace">volga_oauth_client<span class="token punctuation">::</span></span><span class="token punctuation">{</span><span class="token class-name">AuthorizationRequest</span><span class="token punctuation">,</span> <span class="token class-name">AuthorizationServerMetadata</span><span class="token punctuation">,</span> <span class="token class-name">ClientError</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function-definition function">check</span><span class="token punctuation">(</span></span>
<span class="line">    request<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token class-name">AuthorizationRequest</span><span class="token punctuation">,</span></span>
<span class="line">    metadata<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token class-name">AuthorizationServerMetadata</span><span class="token punctuation">,</span></span>
<span class="line">    state<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token keyword">str</span><span class="token punctuation">,</span></span>
<span class="line">    iss<span class="token punctuation">:</span> <span class="token class-name">Option</span><span class="token operator">&lt;</span><span class="token operator">&amp;</span><span class="token keyword">str</span><span class="token operator">&gt;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Result</span><span class="token operator">&lt;</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">ClientError</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    request<span class="token punctuation">.</span><span class="token function">validate_callback</span><span class="token punctuation">(</span>metadata<span class="token punctuation">,</span> state<span class="token punctuation">,</span> iss<span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name">Ok</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>iss</code> is the callback&#39;s <code>iss</code> query parameter, or <code>None</code> when the response carried none. It must match the issuer whenever it is present, and it is <strong>required</strong> once the server advertises <code>authorization_response_iss_parameter_supported</code>.</p><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Without the <code>iss</code> check, a callback can be replayed from a <em>different</em> authorization server — the mix-up attack RFC 9207 exists to prevent. If your provider advertises the parameter, use <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.AuthorizationRequest.html#method.validate_callback" target="_blank" rel="noopener noreferrer"><code>validate_callback</code></a>; <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.AuthorizationRequest.html#method.matches_state" target="_blank" rel="noopener noreferrer"><code>matches_state</code></a> remains for the <code>state</code>-only check.</p></div><h3 id="transparent-refresh" tabindex="-1"><a class="header-anchor" href="#transparent-refresh"><span>Transparent refresh</span></a></h3><p><a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.OAuthClient.html#method.token" target="_blank" rel="noopener noreferrer"><code>token(key, &amp;metadata)</code></a> reads the stored tokens and refreshes a stale access token behind the scenes. It returns <code>Ok(None)</code> when interactive authorization is required — nothing is stored, the entry has no refresh token, or the server rejected the refresh token (<code>invalid_grant</code>); in the latter cases the dead entry is removed from the store. You can also refresh explicitly with <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.OAuthClient.html#method.refresh" target="_blank" rel="noopener noreferrer"><code>refresh</code></a>.</p><h2 id="client-authentication" tabindex="-1"><a class="header-anchor" href="#client-authentication"><span>Client Authentication</span></a></h2><p>Without a credential the client acts as a <strong>public client</strong> (PKCE is the protection OAuth 2.1 prescribes). A confidential client authenticates to the token endpoint with one of three methods, and the choice applies to every grant it sends.</p><h3 id="shared-secret" tabindex="-1"><a class="header-anchor" href="#shared-secret"><span>Shared secret</span></a></h3><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">use</span> <span class="token namespace">volga_oauth_client<span class="token punctuation">::</span></span><span class="token punctuation">{</span><span class="token class-name">ClientAuthMethod</span><span class="token punctuation">,</span> <span class="token class-name">OAuthClient</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> client <span class="token operator">=</span> <span class="token class-name">OAuthClient</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token string">&quot;my-client&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">with_secret</span><span class="token punctuation">(</span><span class="token string">&quot;s3cret&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token comment">// \`client_secret_basic\` (default) or \`client_secret_post\`</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">with_auth_method</span><span class="token punctuation">(</span><span class="token class-name">ClientAuthMethod</span><span class="token punctuation">::</span><span class="token class-name">Post</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="private-key-jwt" tabindex="-1"><a class="header-anchor" href="#private-key-jwt"><span><code>private_key_jwt</code></span></a></h3><p>Since <strong>v0.9.8</strong> (feature <code>private-key-jwt</code>), the client can authenticate with an assertion signed by its own key (RFC 7523 §2.2), so no shared secret ever leaves it:</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">use</span> <span class="token namespace">volga_oauth_client<span class="token punctuation">::</span></span><span class="token punctuation">{</span><span class="token class-name">ClientError</span><span class="token punctuation">,</span> <span class="token class-name">JwsAlgorithm</span><span class="token punctuation">,</span> <span class="token class-name">OAuthClient</span><span class="token punctuation">,</span> <span class="token class-name">PrivateKeyJwt</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function-definition function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Result</span><span class="token operator">&lt;</span><span class="token class-name">OAuthClient</span><span class="token punctuation">,</span> <span class="token class-name">ClientError</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> key <span class="token operator">=</span> <span class="token class-name">PrivateKeyJwt</span><span class="token punctuation">::</span><span class="token function">from_pem_file</span><span class="token punctuation">(</span><span class="token string">&quot;/etc/secrets/client.pem&quot;</span><span class="token punctuation">,</span> <span class="token class-name">JwsAlgorithm</span><span class="token punctuation">::</span><span class="token constant">RS256</span><span class="token punctuation">)</span><span class="token operator">?</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">with_key_id</span><span class="token punctuation">(</span><span class="token string">&quot;2026-08&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token class-name">Ok</span><span class="token punctuation">(</span><span class="token class-name">OAuthClient</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token string">&quot;my-client&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">with_private_key_jwt</span><span class="token punctuation">(</span>key<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.PrivateKeyJwt.html" target="_blank" rel="noopener noreferrer"><code>PrivateKeyJwt</code></a> loads the key (<a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.PrivateKeyJwt.html#method.from_pem" target="_blank" rel="noopener noreferrer"><code>from_pem</code></a>, <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.PrivateKeyJwt.html#method.from_pem_file" target="_blank" rel="noopener noreferrer"><code>from_pem_file</code></a>, <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.PrivateKeyJwt.html#method.from_der" target="_blank" rel="noopener noreferrer"><code>from_der</code></a>) and carries the claims policy — <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.PrivateKeyJwt.html#method.with_key_id" target="_blank" rel="noopener noreferrer"><code>with_key_id</code></a>, <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.PrivateKeyJwt.html#method.with_lifetime" target="_blank" rel="noopener noreferrer"><code>with_lifetime</code></a> (60 seconds by default) and <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.PrivateKeyJwt.html#method.with_audiences" target="_blank" rel="noopener noreferrer"><code>with_audiences</code></a>. A fresh assertion with a random <code>jti</code> is minted per token request, so a captured one is not replayable for long. Attaching it supersedes any <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.OAuthClient.html#method.with_secret" target="_blank" rel="noopener noreferrer"><code>with_secret</code></a> — the assertion is the credential.</p><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Symmetric algorithms are refused: an HMAC secret the server already holds proves nothing about who signed. The algorithm is also checked against the server&#39;s <code>token_endpoint_auth_signing_alg_values_supported</code> when it advertises one.</p></div><h3 id="publishing-the-public-key" tabindex="-1"><a class="header-anchor" href="#publishing-the-public-key"><span>Publishing the public key</span></a></h3><p>The authorization server verifies assertions with the public half of the key, which it either fetches from a <code>jwks_uri</code> or received inline at registration. <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.PrivateKeyJwt.html#method.with_public_jwk" target="_blank" rel="noopener noreferrer"><code>with_public_jwk</code></a> attaches it and <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.PrivateKeyJwt.html#method.jwks" target="_blank" rel="noopener noreferrer"><code>jwks()</code></a> renders the document to publish:</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">use</span> <span class="token namespace">volga_oauth_client<span class="token punctuation">::</span></span><span class="token punctuation">{</span><span class="token class-name">ClientError</span><span class="token punctuation">,</span> <span class="token class-name">JwsAlgorithm</span><span class="token punctuation">,</span> <span class="token class-name">PrivateKeyJwt</span><span class="token punctuation">,</span> <span class="token class-name">PublicJwk</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function-definition function">publish</span><span class="token punctuation">(</span>key<span class="token punctuation">:</span> <span class="token class-name">PrivateKeyJwt</span><span class="token punctuation">,</span> public<span class="token punctuation">:</span> <span class="token class-name">PublicJwk</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Result</span><span class="token operator">&lt;</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">ClientError</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> key <span class="token operator">=</span> key<span class="token punctuation">.</span><span class="token function">with_public_jwk</span><span class="token punctuation">(</span>public<span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// serve this at your \`jwks_uri\`, or send it as the \`jwks\` member of a</span></span>
<span class="line">    <span class="token comment">// Dynamic Client Registration request</span></span>
<span class="line">    <span class="token keyword">let</span> document <span class="token operator">=</span> key<span class="token punctuation">.</span><span class="token function">jwks</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name">Ok</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://docs.rs/volga-oauth-core/latest/volga_oauth_core/jwk/struct.PublicJwk.html" target="_blank" rel="noopener noreferrer"><code>PublicJwk</code></a> (RFC 7517, in <code>volga-oauth-core</code>) models <strong>public</strong> signing material exclusively — there is no way to represent the private members, and deserializing a document that carries them fails rather than silently dropping them. It also refuses combinations no verifier could act on: an RSA key declaring <code>ES256</code>, a P-384 key declaring <code>ES256</code>, a public key declaring an HMAC algorithm, or a curve that does not belong to the key type. <code>kid</code> and <code>alg</code> are filled in from the signing configuration, so the published document always agrees with what the assertions actually carry.</p><div class="hint-container info"><p class="hint-container-title">Info</p><p>Supply the <em>public</em> key explicitly — the crate signs, it does not derive public keys from private ones. That is also what makes publishing the signing key by accident impossible.</p></div><h3 id="what-is-checked-before-the-request-leaves" tabindex="-1"><a class="header-anchor" href="#what-is-checked-before-the-request-leaves"><span>What is checked before the request leaves</span></a></h3><p>Since <strong>v0.9.8</strong> the configured method is validated against <code>token_endpoint_auth_methods_supported</code> before a token request is sent: a method the server never announced would only earn an <code>invalid_client</code> over the network. Metadata listing no methods is not second-guessed — that is what a hand-built <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.AuthorizationServerMetadata.html" target="_blank" rel="noopener noreferrer"><code>AuthorizationServerMetadata</code></a> carries — but a <em>discovered</em> document always lists something, since RFC 8414 makes an omitted field mean <code>client_secret_basic</code>. A public client presents no credential and is never checked.</p><div class="hint-container info"><p class="hint-container-title">Info</p><p>The registered wire identifiers both sides of the protocol agree on live in one place since <strong>v0.9.8</strong> — <code>volga_oauth_core::protocol</code>, as the <code>grant</code>, <code>client_auth</code>, <code>token_type</code> and <code>auth_scheme</code> constants, re-exported from both <code>volga::auth::oauth</code> and <code>volga_oauth_client</code>. A server advertises them in its metadata document and a client matches on them, so the two cannot drift.</p></div><h2 id="token-store" tabindex="-1"><a class="header-anchor" href="#token-store"><span>Token Store</span></a></h2><p>Persistence goes through the <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/trait.TokenStore.html" target="_blank" rel="noopener noreferrer"><code>TokenStore</code></a> trait. <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.InMemoryTokenStore.html" target="_blank" rel="noopener noreferrer"><code>InMemoryTokenStore</code></a> is the built-in process-local implementation — suitable for CLIs, tests and single-instance services; anything durable (a database, an encrypted file, an OS keychain) is one trait impl away.</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">use</span> <span class="token namespace">volga_oauth_client<span class="token punctuation">::</span></span><span class="token punctuation">{</span><span class="token class-name">TokenSet</span><span class="token punctuation">,</span> <span class="token class-name">TokenStore</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">struct</span> <span class="token type-definition class-name">MyStore</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">impl</span> <span class="token class-name">TokenStore</span> <span class="token keyword">for</span> <span class="token class-name">MyStore</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">fn</span> <span class="token function-definition function">get</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">,</span> key<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token keyword">str</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Option</span><span class="token operator">&lt;</span><span class="token class-name">TokenSet</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span> <span class="token comment">/* ... */</span> <span class="token class-name">None</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">fn</span> <span class="token function-definition function">put</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">,</span> key<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token keyword">str</span><span class="token punctuation">,</span> tokens<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token class-name">TokenSet</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token comment">/* ... */</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">fn</span> <span class="token function-definition function">remove</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">self</span><span class="token punctuation">,</span> key<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token keyword">str</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token comment">/* ... */</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The key is chosen by the application — typically a user or session identifier, combined with the resource when one client serves several audiences. A <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.TokenSet.html" target="_blank" rel="noopener noreferrer"><code>TokenSet</code></a> carries the access token, an optional refresh token, the granted scope, the OIDC <code>id_token</code> (passed through, not validated) and an absolute <code>expires_at</code>; tokens are redacted from its <code>Debug</code> output.</p><h2 id="dynamic-client-registration" tabindex="-1"><a class="header-anchor" href="#dynamic-client-registration"><span>Dynamic Client Registration</span></a></h2><p><a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.RegistrationClient.html" target="_blank" rel="noopener noreferrer"><code>RegistrationClient</code></a> submits <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.ClientMetadata.html" target="_blank" rel="noopener noreferrer"><code>ClientMetadata</code></a> to a server&#39;s registration endpoint (RFC 7591) and returns the issued credentials. <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.OAuthClient.html#method.from_registration" target="_blank" rel="noopener noreferrer"><code>OAuthClient::from_registration</code></a> adopts them into a ready-to-use client:</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">use</span> <span class="token namespace">volga_oauth_client<span class="token punctuation">::</span></span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">ClientError</span><span class="token punctuation">,</span> <span class="token class-name">ClientMetadata</span><span class="token punctuation">,</span> <span class="token class-name">DiscoveryClient</span><span class="token punctuation">,</span> <span class="token class-name">OAuthClient</span><span class="token punctuation">,</span> <span class="token class-name">RegistrationClient</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">async</span> <span class="token keyword">fn</span> <span class="token function-definition function">register</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Result</span><span class="token operator">&lt;</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">ClientError</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> metadata <span class="token operator">=</span> <span class="token class-name">DiscoveryClient</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">fetch_server_metadata</span><span class="token punctuation">(</span><span class="token string">&quot;https://auth.example.com&quot;</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">let</span> registered <span class="token operator">=</span> <span class="token class-name">RegistrationClient</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">register</span><span class="token punctuation">(</span></span>
<span class="line">            <span class="token operator">&amp;</span>metadata<span class="token punctuation">,</span></span>
<span class="line">            <span class="token operator">&amp;</span><span class="token class-name">ClientMetadata</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">                <span class="token punctuation">.</span><span class="token function">with_redirect_uris</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string">&quot;https://app.example.com/callback&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line">                <span class="token punctuation">.</span><span class="token function">with_client_name</span><span class="token punctuation">(</span><span class="token string">&quot;My App&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// ready-to-use client under the issued credentials</span></span>
<span class="line">    <span class="token keyword">let</span> client <span class="token operator">=</span> <span class="token class-name">OAuthClient</span><span class="token punctuation">::</span><span class="token function">from_registration</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>registered<span class="token punctuation">)</span><span class="token operator">?</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token class-name">Ok</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>For servers that do not allow open registration, attach an initial access token with <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.RegistrationClient.html#method.with_initial_access_token" target="_blank" rel="noopener noreferrer"><code>with_initial_access_token</code></a>.</p><p>Two <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.ClientMetadata.html" target="_blank" rel="noopener noreferrer"><code>ClientMetadata</code></a> fields became first-class in <strong>v0.9.6</strong> and <strong>v0.9.8</strong> respectively:</p><ul><li><a href="https://docs.rs/volga-oauth-core/latest/volga_oauth_core/struct.ClientMetadata.html#method.with_application_type" target="_blank" rel="noopener noreferrer"><code>with_application_type</code></a> — <code>&quot;web&quot;</code> or <code>&quot;native&quot;</code>. Desktop and CLI clients register as <code>&quot;native&quot;</code>, which is what makes loopback redirect URIs (<code>http://127.0.0.1:{port}/...</code>) acceptable to authorization servers.</li><li><a href="https://docs.rs/volga-oauth-core/latest/volga_oauth_core/struct.ClientMetadata.html#method.with_token_endpoint_auth_signing_alg" target="_blank" rel="noopener noreferrer"><code>with_token_endpoint_auth_signing_alg</code></a> — the algorithm this one client signs its assertions with, for a <code>private_key_jwt</code> registration.</li></ul><p>When the registration authenticates with <code>private_key_jwt</code>, adopt it with <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.OAuthClient.html#method.from_registration_with_key" target="_blank" rel="noopener noreferrer"><code>from_registration_with_key</code></a>, which also refuses a key the registration would not accept — one signing with an algorithm other than the registered <code>token_endpoint_auth_signing_alg</code>, or carrying a <code>kid</code> an inlined <code>jwks</code> cannot resolve:</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">use</span> <span class="token namespace">volga_oauth_client<span class="token punctuation">::</span></span><span class="token punctuation">{</span><span class="token class-name">ClientError</span><span class="token punctuation">,</span> <span class="token class-name">ClientRegistrationResponse</span><span class="token punctuation">,</span> <span class="token class-name">OAuthClient</span><span class="token punctuation">,</span> <span class="token class-name">PrivateKeyJwt</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">fn</span> <span class="token function-definition function">adopt</span><span class="token punctuation">(</span></span>
<span class="line">    registered<span class="token punctuation">:</span> <span class="token operator">&amp;</span><span class="token class-name">ClientRegistrationResponse</span><span class="token punctuation">,</span></span>
<span class="line">    key<span class="token punctuation">:</span> <span class="token class-name">PrivateKeyJwt</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">Result</span><span class="token operator">&lt;</span><span class="token class-name">OAuthClient</span><span class="token punctuation">,</span> <span class="token class-name">ClientError</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">OAuthClient</span><span class="token punctuation">::</span><span class="token function">from_registration_with_key</span><span class="token punctuation">(</span>registered<span class="token punctuation">,</span> key<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Since <strong>v0.9.8</strong>, a client built by <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.OAuthClient.html#method.from_registration" target="_blank" rel="noopener noreferrer"><code>from_registration</code></a> refuses a grant its registration did not approve — before reaching the network, rather than as an <code>unauthorized_client</code> from the token endpoint. An omitted <code>grant_types</code> means <code>authorization_code</code> alone (RFC 7591 §2), not carte blanche; only a client that never went through a registration is unconstrained. <code>refresh_token</code> is never refused, since RFC 6749 §6 makes it the continuation of a grant already held.</p></div><div class="hint-container info"><p class="hint-container-title">Info</p><p>The RFC 7592 management protocol (reading, updating and deleting a registration) is not implemented, but the <code>registration_access_token</code> / <code>registration_client_uri</code> pair from the response is surfaced for applications that need it.</p></div><h2 id="transport-policy-errors" tabindex="-1"><a class="header-anchor" href="#transport-policy-errors"><span>Transport Policy &amp; Errors</span></a></h2><p><a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.ClientConfig.html" target="_blank" rel="noopener noreferrer"><code>ClientConfig</code></a> carries the policy shared by every client operation — HTTPS enforcement, per-request timeouts and redirect limits. The defaults are safe for production; the most common override is disabling HTTPS for a local development server:</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">use</span> <span class="token namespace">std<span class="token punctuation">::</span>time<span class="token punctuation">::</span></span><span class="token class-name">Duration</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">use</span> <span class="token namespace">volga_oauth_client<span class="token punctuation">::</span></span><span class="token punctuation">{</span><span class="token class-name">ClientConfig</span><span class="token punctuation">,</span> <span class="token class-name">OAuthClient</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> config <span class="token operator">=</span> <span class="token class-name">ClientConfig</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">require_https</span><span class="token punctuation">(</span><span class="token boolean">false</span><span class="token punctuation">)</span>              <span class="token comment">// local development only</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">with_timeout</span><span class="token punctuation">(</span><span class="token class-name">Duration</span><span class="token punctuation">::</span><span class="token function">from_secs</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token function">with_max_redirects</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> client <span class="token operator">=</span> <span class="token class-name">OAuthClient</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token string">&quot;my-client&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">with_config</span><span class="token punctuation">(</span>config<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/enum.ClientError.html" target="_blank" rel="noopener noreferrer"><code>ClientError</code></a> separates a parsed OAuth error response (<code>Protocol</code>, carrying the RFC 6749 §5.2 <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/struct.OAuthError.html" target="_blank" rel="noopener noreferrer"><code>OAuthError</code></a>) from transport, decode, insecure-URL and validation failures — so you can distinguish &quot;the server said <code>invalid_grant</code>&quot; from &quot;the connection dropped&quot;. Since <strong>v0.9.8</strong> it also carries <code>Signing</code>, for a signing configuration that cannot produce the JWS a request needs — a <code>private_key_jwt</code> assertion or a DPoP proof.</p><h3 id="propagating-errors-from-a-handler" tabindex="-1"><a class="header-anchor" href="#propagating-errors-from-a-handler"><span>Propagating errors from a handler</span></a></h3><p>Since <strong>v0.9.8</strong>, with the <code>oauth-client</code> feature enabled on <code>volga</code>, a <a href="https://docs.rs/volga-oauth-client/latest/volga_oauth_client/enum.ClientError.html" target="_blank" rel="noopener noreferrer"><code>ClientError</code></a> converts into a <a href="https://docs.rs/volga/latest/volga/error/struct.Error.html" target="_blank" rel="noopener noreferrer"><code>volga::Error</code></a>, so a handler that talks to an authorization server can propagate the failure with <code>?</code>:</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">use</span> <span class="token namespace">volga<span class="token punctuation">::</span></span><span class="token punctuation">{</span><span class="token class-name">HttpResult</span><span class="token punctuation">,</span> ok<span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">use</span> <span class="token namespace">volga_oauth_client<span class="token punctuation">::</span></span><span class="token punctuation">{</span><span class="token class-name">DiscoveryClient</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">async</span> <span class="token keyword">fn</span> <span class="token function-definition function">metadata</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">-&gt;</span> <span class="token class-name">HttpResult</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">let</span> metadata <span class="token operator">=</span> <span class="token class-name">DiscoveryClient</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">fetch_server_metadata</span><span class="token punctuation">(</span><span class="token string">&quot;https://auth.example.com&quot;</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token keyword">await</span><span class="token operator">?</span><span class="token punctuation">;</span> <span class="token comment">// ClientError -&gt; volga::Error</span></span>
<span class="line"></span>
<span class="line">    <span class="token macro property">ok!</span><span class="token punctuation">(</span>metadata<span class="token punctuation">.</span>issuer<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The status describes <strong>where</strong> the failure sits rather than echoing what the authorization server answered — this application was the <em>client</em> of the call that failed:</p><table><thead><tr><th>Failure</th><th>Status</th></tr></thead><tbody><tr><td>the server could not be reached (<code>Transport</code>)</td><td><code>503 Service Unavailable</code></td></tr><tr><td>it answered unusably — a protocol error, an unexpected status, an unparseable body</td><td><code>502 Bad Gateway</code></td></tr><tr><td>this application&#39;s own configuration — an insecure URL, metadata that fails validation, a key that cannot sign</td><td><code>500 Internal Server Error</code></td></tr></tbody></table><p>To surface the authorization server&#39;s own error code to your caller, match on <code>ClientError::Protocol</code> instead of relying on the conversion.</p><h2 id="what-s-next" tabindex="-1"><a class="header-anchor" href="#what-s-next"><span>What&#39;s next</span></a></h2>`,66)),s("ul",null,[s("li",null,[t(e,{to:"/en/security-access/machine-to-machine.html"},{default:o(()=>n[17]||(n[17]=[a("Machine-to-Machine Grants")])),_:1,__:[17]}),n[18]||(n[18]=a(" — ")),n[19]||(n[19]=s("code",null,"client_credentials",-1)),n[20]||(n[20]=a(", JWT bearer and token exchange, for flows with no user involved."))]),s("li",null,[t(e,{to:"/en/security-access/dpop.html"},{default:o(()=>n[21]||(n[21]=[a("DPoP")])),_:1,__:[21]}),n[22]||(n[22]=a(" — binding tokens to a key the client holds, so a stolen token is worth nothing."))])]),n[25]||(n[25]=s("h2",{id:"examples",tabindex:"-1"},[s("a",{class:"header-anchor",href:"#examples"},[s("span",null,"Examples")])],-1)),n[26]||(n[26]=s("ul",null,[s("li",null,[s("a",{href:"https://github.com/RomanEmreis/volga/blob/main/examples/oauth_flow/src/main.rs",target:"_blank",rel:"noopener noreferrer"},"OAuth Flow"),a(" — a full discovery → authorization → code exchange → protected call flow driven by "),s("code",null,"volga-oauth-client"),a(".")])],-1))])}const m=c(u,[["render",d]]),v=JSON.parse(`{"path":"/en/security-access/oauth-client.html","title":"OAuth 2.1 Client","lang":"en-US","frontmatter":{},"git":{"updatedTime":1787377224000,"contributors":[{"name":"RomanEmreis","username":"RomanEmreis","email":"39233213+RomanEmreis@users.noreply.github.com","commits":2,"url":"https://github.com/RomanEmreis"},{"name":"Claude Opus 4.8","username":"","email":"noreply@anthropic.com","commits":3},{"name":"Claude","username":"Claude","email":"noreply@anthropic.com","commits":1,"url":"https://github.com/Claude"},{"name":"Claude Opus 5","username":"","email":"noreply@anthropic.com","commits":3}],"changelog":[{"hash":"f7f30b07ef0bbade3b358ae5213f1d0470b609dd","time":1787377224000,"email":"39233213+RomanEmreis@users.noreply.github.com","author":"Roman","message":"Cover releases 0.9.3–0.9.8, and compile-check the site's Rust snippets (#52)","coAuthors":[{"name":"Claude Opus 5","email":"noreply@anthropic.com"},{"name":"Claude Opus 5","email":"noreply@anthropic.com"},{"name":"Claude Opus 5","email":"noreply@anthropic.com"}]},{"hash":"fea58a40ce377b4ee5b5004afaf764e1f76fe213","time":1784129799000,"email":"39233213+RomanEmreis@users.noreply.github.com","author":"Roman","message":"Add OAuth 2.1 &#x26; OpenID Connect documentation (#50)","coAuthors":[{"name":"Claude Opus 4.8","email":"noreply@anthropic.com"},{"name":"Claude Opus 4.8","email":"noreply@anthropic.com"},{"name":"Claude Opus 4.8","email":"noreply@anthropic.com"},{"name":"Claude","email":"noreply@anthropic.com"}]}]},"filePathRelative":"en/security-access/oauth-client.md"}`);export{m as comp,v as data};
